function message(e,n,...o){if((o=o.filter(Boolean)).length>2){const n=o.pop();e+=`one of type ${o.join(", ")}, or ${n}.`}else 2===o.length?e+=`one of type ${o[0]} or ${o[1]}.`:e+=`of type ${o[0]}.`;return null==n?e+=` Received ${n}`:"function"==typeof n&&n.name?e+=` Received function ${n.name}`:"object"==typeof n&&null!=n&&n.constructor?.name&&(e+=` Received an instance of ${n.constructor.name}`),e}export const invalidKeyInput=(e,...n)=>message("Key must be ",e,...n);export const withAlg=(e,n,...o)=>message(`Key for the ${e} algorithm must be `,n,...o);